#include <iostream>
int search(const int values[],int target,int low,int high){if(low>high)return -1;int middle=low+(high-low)/2;if(values[middle]==target)return middle;if(target<values[middle])return search(values,target,low,middle-1);return search(values,target,middle+1,high);}
int main(){int n;std::cout<<"Enter array size (1-100): ";if(!(std::cin>>n)||n<1||n>100){std::cout<<"Array size must be from 1 to 100.\n";return 0;}int values[100];std::cout<<"Enter sorted values: ";for(int i=0;i<n;++i){if(!(std::cin>>values[i])){std::cout<<"Enter all values and a target.\n";return 0;}if(i>0&&values[i]<values[i-1]){std::cout<<"Values must be sorted in ascending order.\n";return 0;}}int target;if(!(std::cin>>target)){std::cout<<"Enter a target whole number.\n";return 0;}if(std::cin>>std::ws&&std::cin.peek()!=std::char_traits<char>::eof()){std::cout<<"Enter only the values and one target.\n";return 0;}int index=search(values,target,0,n-1);if(index<0)std::cout<<"Not found\n";else std::cout<<"Found at index "<<index<<'\n';}
